mapper.select:
SELECT

FROM t_compensation_event
WHERE id = #{eventId}
AND execute_status = 'PROCESSING'
AND lock_owner = #{lockOwner}
AND lock_until > UTC_TIMESTAMP(6)

SELECT id FROM t_compensation_event WHERE ( ( execute_status IN ('INIT', 'ERROR') AND next_execute_at <= UTC_TIMESTAMP(6) ) OR ( execute_status = 'PROCESSING' AND lock_owner IS NOT NULL AND lock_until IS NOT NULL AND lock_until <= UTC_TIMESTAMP(6) ) ) AND MOD(id, #{shardCount}) = #{shardIndex}
AND event_type IN
#{eventType}
ORDER BY CASE WHEN execute_status = 'PROCESSING' THEN lock_until ELSE next_execute_at END, id LIMIT #{batchSize}

mapper.delete:
